// test_mac_lane_vectors.cpp
//
// Cross-checks the committed mac_lane golden vectors (tb/golden/mac_lane/)
// against model_exact. The vectors are generated by an independent Python
// script; Lane B's RTL testbench asserts against the same files. If all three
// agree, a mismatch in the RTL is an RTL bug, not a disagreement about what
// the right answer is.
//
// Parses the files the way a $readmemh reader sees them: whitespace-separated
// hex words, `//` comments ignored, CR tolerated.

#include <cstdint>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "fecim/model_exact.h"
#include "fecim/params.h"
#include "test_harness.h"

#ifndef FECIM_GOLDEN_DIR
#error "FECIM_GOLDEN_DIR must point at tb/golden (set in model/CMakeLists.txt)"
#endif

using namespace fecim;

namespace {

constexpr int kLane = 5;                   // any lane; not 0, so lane != column
constexpr std::uint32_t kFlagWrite = 0x1u;

std::vector<std::uint32_t> read_hex_words(const std::string& name) {
    const std::string path = std::string(FECIM_GOLDEN_DIR) + "/mac_lane/" + name;
    std::ifstream f(path);
    if (!f) throw std::runtime_error("cannot open " + path);
    std::vector<std::uint32_t> words;
    std::string line;
    while (std::getline(f, line)) {
        const auto c = line.find("//");
        if (c != std::string::npos) line.erase(c);
        std::istringstream ss(line);
        std::string tok;
        while (ss >> tok)
            words.push_back(static_cast<std::uint32_t>(std::stoul(tok, nullptr, 16)));
    }
    return words;
}

std::int32_t as_i32(std::uint32_t w) {
    return static_cast<std::int32_t>(w);   // two's complement, C++17 well-defined here
}

struct Row  { std::int8_t w; std::uint8_t a; std::int32_t running; };
struct Case { int base, n, pass; bool write; std::int32_t expected; };

struct Vectors {
    std::vector<Case> cases;
    std::vector<Row>  rows;
};

Vectors load() {
    const auto cw = read_hex_words("cases.hex");
    const auto rw = read_hex_words("rows.hex");
    if (cw.empty() || rw.empty()) throw std::runtime_error("empty vector file");
    if (cw.size() != 1 + std::size_t{cw[0]} * 5) throw std::runtime_error("cases.hex length");
    if (rw.size() != 1 + std::size_t{rw[0]} * 3) throw std::runtime_error("rows.hex length");

    Vectors v;
    for (std::size_t i = 0; i < cw[0]; ++i) {
        const std::uint32_t* f = &cw[1 + i * 5];
        v.cases.push_back({static_cast<int>(f[0]), static_cast<int>(f[1]),
                           static_cast<int>(f[2]), (f[3] & kFlagWrite) != 0,
                           as_i32(f[4])});
    }
    for (std::size_t j = 0; j < rw[0]; ++j) {
        const std::uint32_t* f = &rw[1 + j * 3];
        if (f[0] > 0xFFu || f[1] > 0xFFu) throw std::runtime_error("row field width");
        v.rows.push_back({static_cast<std::int8_t>(static_cast<std::uint8_t>(f[0])),
                          static_cast<std::uint8_t>(f[1]), as_i32(f[2])});
    }
    return v;
}

} // namespace

// The files are well-formed: cases tile rows.hex exactly, fields in range.
TEST(mac_lane_vectors_well_formed) {
    const Vectors v = load();
    CHECK(!v.cases.empty());
    int next = 0;
    for (const Case& c : v.cases) {
        CHECK_EQ(c.base, next);
        CHECK(c.n >= 1 && c.n <= TILE_ROWS);
        CHECK(c.pass >= 0 && c.pass < PASSES);
        next = c.base + c.n;
    }
    CHECK_EQ(static_cast<std::size_t>(next), v.rows.size());
}

// Running sums are self-consistent and every value fits ACC_USED_W.
TEST(mac_lane_vectors_running_sums) {
    const Vectors v = load();
    const std::int64_t lim = std::int64_t{1} << (ACC_USED_W - 1);
    for (const Case& c : v.cases) {
        std::int64_t acc = 0;
        for (int r = 0; r < c.n; ++r) {
            const Row& row = v.rows[static_cast<std::size_t>(c.base + r)];
            acc += std::int64_t{row.w} * std::int64_t{row.a};
            CHECK_EQ(std::int64_t{row.running}, acc);
            CHECK(acc >= -lim && acc < lim);
        }
        CHECK_EQ(std::int64_t{c.expected}, acc);
    }
}

// Cases without the WRITE flag only make sense if the lane memory, replayed in
// file order, already holds exactly those weights.
TEST(mac_lane_vectors_memory_replay) {
    const Vectors v = load();
    std::vector<int> mem(static_cast<std::size_t>(TILE_ROWS * PASSES), 1000);  // 1000 = unwritten
    for (const Case& c : v.cases) {
        for (int r = 0; r < c.n; ++r) {
            const auto addr = static_cast<std::size_t>(c.pass * TILE_ROWS + r);
            const int w = v.rows[static_cast<std::size_t>(c.base + r)].w;
            if (c.write) mem[addr] = w;
            else         CHECK_EQ(mem[addr], w);
        }
    }
}

// The real cross-check: replay every case through model_exact on one lane's
// column, in file order, writing weights only where the vectors do.
TEST(mac_lane_vectors_match_model_exact) {
    const Vectors v = load();
    ModelExact m;
    Config cfg;                                     // reset defaults: clean
    for (const Case& c : v.cases) {
        const int col = c.pass * NUM_LANES + kLane; // lane-local addr pass*ROWS + r
        for (int r = 0; r < c.n; ++r) {
            const Row& row = v.rows[static_cast<std::size_t>(c.base + r)];
            if (c.write) m.write_weight(r, col, row.w);
            CHECK_EQ(m.stored_weight(r, col), row.w);
            m.write_activation(r, row.a);
        }
        cfg.active_rows = c.n;
        m.set_config(cfg);
        const auto y = m.compute();
        CHECK_EQ(y.at(static_cast<std::size_t>(col)), c.expected);
    }
}
